package com.himeros.trustsafety;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="blocks")class Block{@Id private UUID id;@Column(name="blocker_id",nullable=false)private UUID blocker;@Column(name="blocked_id",nullable=false)private UUID blocked;@Column(name="created_at",nullable=false)private Instant created;protected Block(){}Block(UUID a,UUID b){id=UUID.randomUUID();blocker=a;blocked=b;created=Instant.now();}}
